package com.dormrepair.v2.preparation;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.flywaydb.core.Flyway;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="flowable.v2B",matches="true")
class PreparationMigrationTest {
 DriverManagerDataSource ds;JdbcTemplate j;
 @BeforeEach void reset()throws Exception{ds=new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:5432/dorm_repair_v2_test_grantsd",System.getenv().getOrDefault("V2_DB_USER","sota"),System.getenv().getOrDefault("V2_DB_PASSWORD",""));try(var c=ds.getConnection()){com.dormrepair.v2.platform.migration.V2DatabaseTarget.requireTestReset(c);}j=new JdbcTemplate(ds);j.execute("drop schema if exists v2_business_history cascade");j.execute("drop schema public cascade");j.execute("create schema public");}
 Flyway migrate(String target,String init){var config=Flyway.configure().dataSource(ds).locations("classpath:db/v2/business").defaultSchema("v2_business_history").schemas("v2_business_history").group(true).target(target.equals("latest")?"10":target);if(init!=null)config.initSql(init);var f=config.load();f.migrate();return f;}
 String mapping(){return "create temporary table c6_confirmed_grants(role_id bigint,permission_code varchar(80),primary key(role_id,permission_code));insert into c6_confirmed_grants select r.id,p.code from public.sys_role r cross join public.sys_permission p where r.code='ADMIN' and p.code in ('category:write','space:write','facility:write');";}
 void users(){j.update("insert into public.sys_user(username,password_hash,real_name,role) values ('synthetic_admin','unchanged','Synthetic admin','ADMIN'),('synthetic_student','unchanged','Synthetic student','STUDENT')");}

 String dMapping(){return "create temporary table c7_confirmed_user_grants(user_id bigint,permission_code varchar(80),primary key(user_id,permission_code));insert into c7_confirmed_user_grants select id,p from public.sys_user cross join (values ('address:own'),('residency:own'),('residency:manage'),('draft:own')) x(p) where username='synthetic_admin';insert into c7_confirmed_user_grants select id,p from public.sys_user cross join (values ('address:own'),('residency:own'),('draft:own')) x(p) where username='synthetic_student';";}
 @Test void blankMigrationAndRepeatCreatesNoFormalRecords(){migrate("latest",null);assertEquals(23,j.queryForObject("select count(*) from information_schema.tables where table_schema='public' and table_type='BASE TABLE'",Integer.class));assertEquals(20,j.queryForObject("select count(*) from public.sys_permission",Integer.class));assertEquals(0,j.queryForObject("select count(*) from public.repair_order",Integer.class));assertEquals(0,migrate("latest",null).migrate().migrationsExecuted);}
 @Test void v6EmptyMigrationPreservesSourceRows(){migrate("6",null);j.update("insert into public.campus(code,name) values ('SYNTHETIC_D','Synthetic campus')");var before=j.queryForList("select * from public.campus");var checksums=j.queryForList("select version,checksum from v2_business_history.flyway_schema_history where version is not null order by installed_rank");migrate("latest",null);assertEquals(before,j.queryForList("select * from public.campus"));assertEquals(checksums,j.queryForList("select version,checksum from v2_business_history.flyway_schema_history where version::int<=6 order by installed_rank"));}
 @Test void customEmptyRoleRefusesBeforeCreatingTables(){migrate("6",null);j.update("insert into public.sys_role(code,name) values ('CUSTOM','Unknown provenance')");assertThrows(Exception.class,()->migrate("latest",null));assertNull(j.queryForObject("select to_regclass('public.user_address')::text",String.class));assertEquals(16,j.queryForObject("select count(*) from public.sys_permission",Integer.class));}
 @Test void nonemptyWithoutMappingRefusesAndPreservesGrants(){migrate("6",null);users();var before=j.queryForList("select * from public.sys_role_permission order by role_id,permission_id");assertThrows(Exception.class,()->migrate("latest",null));assertEquals(before,j.queryForList("select * from public.sys_role_permission order by role_id,permission_id"));assertEquals(0,j.queryForObject("select sum(auth_version) from public.sys_user",Integer.class));assertNull(j.queryForObject("select to_regclass('public.repair_draft')::text",String.class));}
 @Test void perUserGrantDoesNotExpandSharedRole(){migrate("6",null);users();j.update("insert into public.sys_user_role select u.id,r.id from public.sys_user u cross join public.sys_role r where u.username='synthetic_admin' and r.code='STUDENT'");var shared=j.queryForList("select rp.* from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id where r.code='STUDENT' order by rp.permission_id");migrate("latest",dMapping());assertEquals(shared,j.queryForList("select rp.* from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id where r.code='STUDENT' order by rp.permission_id"));long student=j.queryForObject("select id from public.sys_user where username='synthetic_student'",Long.class);assertFalse(new com.dormrepair.v2.identity.RbacRepository(j).permissions(student).contains("residency:manage"));assertEquals(1,new com.dormrepair.v2.identity.RbacRepository(j).managers());assertEquals(2,j.queryForObject("select sum(auth_version) from public.sys_user",Integer.class));}
 @Test void incompleteMappingRollsBackPermissionAndSupplementRoles(){migrate("6",null);users();assertThrows(Exception.class,()->migrate("latest","create temporary table c7_confirmed_user_grants(user_id bigint,permission_code varchar(80));insert into c7_confirmed_user_grants select id,'draft:own' from public.sys_user where username='synthetic_student';"));assertEquals(16,j.queryForObject("select count(*) from public.sys_permission",Integer.class));assertEquals(3,j.queryForObject("select count(*) from public.sys_role",Integer.class));assertEquals(0,j.queryForObject("select sum(auth_version) from public.sys_user",Integer.class));assertEquals(2,j.queryForObject("select count(*) from public.sys_user_role",Integer.class));}
 @Test void modifiedKnownSeedTemplatesRefuseWithoutCommit(){migrate("6",null);j.update("delete from public.sys_role_permission where role_id=(select id from public.sys_role where code='ADMIN') and permission_id=(select id from public.sys_permission where code='role:manage')");assertThrows(Exception.class,()->migrate("latest",null));assertEquals(16,j.queryForObject("select count(*) from public.sys_permission",Integer.class));assertNull(j.queryForObject("select to_regclass('public.user_address')::text",String.class));}
}
